LEVEL = 1
CFG = {1: {"batch": 1}, 2: {"batch": 3}, 3: {"batch": 5}}
B = CFG[LEVEL]
log, applied, balance = [], [], 100
def apply(op):
    log.append(op)  # write ahead, before applying
    if len(log) % B["batch"] == 0:
        for e in log:
            if e not in applied:
                applied.append(e)
ops = [{"delta": d} for d in (10, -4, 25, -7, 12)]
for op in ops[:3]:
    apply(op)  # crash happens here; unflushed tail survives in the log
for e in log + ops[3:]:  # resume: replay the log tail
    if e not in applied:
        applied.append(e)
balance = 100 + sum(o["delta"] for o in applied)
print("recovered balance:", balance, "| expected:", 100 + sum(o["delta"] for o in ops))

