LEVEL = 1
CFG = {1: ["a","b","c","b","d","a"], 2: ["a","b","c","b","d","a","e","c"], 3: ["a","b","c","b","d","a","e","c","f","d"]}
KEYS = CFG[LEVEL]
applied, effects = set(), []
for k in KEYS:
    if k in applied:
        continue  # already applied: skip on resume/retry
    applied.add(k); effects.append("effect:" + k)
print("applied keys:", sorted(applied))
print("effects:", effects, "| duplicates suppressed:", len(KEYS) - len(effects))

