LEVEL = 1
CFG = {1: {"lease": 3}, 2: {"lease": 3}, 3: {"lease": 2}}
LEASE = CFG[LEVEL]["lease"]
workers = {"w1": {"until": 3, "ckpt": 40}, "w2": {"until": 9, "ckpt": 10}}
reassigned = set(); events = []
for now in range(10):
    for wid, w in workers.items():
        if wid == "w1" and now >= 4:
            continue  # w1 dies: no more heartbeats
        w["until"] = now + LEASE; w["ckpt"] += 10
    for wid, w in workers.items():
        if w["until"] < now and wid not in reassigned:
            reassigned.add(wid)
            events.append("t=%d reassign %s from checkpoint %d" % (now, wid, w["ckpt"]))
print("events:", events or ["no expiries"])
print("w2 kept working, checkpoint:", workers["w2"]["ckpt"])

