LEVEL = 1
CFG = {1: ["a","b"], 2: ["a","b","c"], 3: ["a","b","c","d"]}
FIELDS = CFG[LEVEL]
base = {f: 0 for f in FIELDS}
deltas = [{f: i for f in FIELDS[: i % len(FIELDS) + 1]} for i in range(1, 6)]
state = dict(base)
for d in deltas:
    state.update(d)  # fold each differential checkpoint
expected = dict(base)
for d in deltas:
    expected.update(d)
print("reconstructed == live:", state == expected, "| state:", state)

